// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
    }

    function testFuzz_property(uint256 deposit, uint256 collectAmount, uint256 unlockTime) public {
        vm.assume(deposit <= VALUE_CAP);
        address actor = address(0xBEEF);

        // Keep the domain wide but allow the happy path to be reachable.
        deposit = bound(deposit, 1, 100 ether);
        collectAmount = bound(collectAmount, 0, deposit);
        unlockTime = bound(unlockTime, 1, 1000000000);

        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Put{value: deposit}(unlockTime);

        (uint256 recordedUnlockTime, uint256 balanceBefore) = c.Acc(actor);
        // The contract sets unlockTime to block.timestamp if the requested unlock is in the past.
        vm.assume(balanceBefore >= c.MinSum());
        vm.assume(balanceBefore >= collectAmount);

        // Warp past the effective unlock time so Collect can proceed.
        vm.warp(recordedUnlockTime + 1);

        vm.prank(actor);
        c.Collect(collectAmount);

        (, uint256 balanceAfter) = c.Acc(actor);

        // General rule: a successful Collect must have reduced the caller's balance by exactly collectAmount.
        assertTrue(
            balanceAfter == balanceBefore - collectAmount,
            "Collect did not reduce the caller balance by the requested amount"
        );
    }
}
